INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50911, 'Hosea 7:13', 'Hosea', 7, 13, 'افسوس د هغوی په حال! هغوی زه پریښی یم. هغوی به برباد شي، ځکه چې زما په وړاندې یې سرکښي کړې ده. ما غوښتل چې هغوی وژغورم، خو هغوی ماته وفادار نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_13.mp3', '', 1761754199, 1761754199),
(50912, 'Hosea 7:14', 'Hosea', 7, 14, 'هغوی ماته د زړه د اخلاصه دعا نه کوي، خو هغوی په کټونو باندې ژړا او انګولا کوي. کله چې هغوی د غلو دانو او شرابو په خاطر دعا کوي، نو د کافرانو په شان خپل ځانونه غوڅوي. هغوی زما په خلاف سرکښي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_14.mp3', '', 1761754199, 1761754199),
(50913, 'Hosea 7:15', 'Hosea', 7, 15, 'که څه هم ما د هغوی روزنه وکړه او هغوی مې قوي کړل، خو هغوی زما په وړاندې دسیسه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_15.mp3', '', 1761754199, 1761754199),
(50914, 'Hosea 7:16', 'Hosea', 7, 16, 'هغوی زما یعنې څښتن تعالی په ځای بې‌وسه بتانو ته رجوع کوي. هغوی د کږې لیندې په شان بې‌اعتباره دي. د هغوی مشران زما په خلاف د غرور نه ډکې خبرې کوي، نو هغوی به په توره باندې مړه شي او مصریان به هغوی پورې خاندي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_16.mp3', '', 1761754199, 1761754199),
(50915, 'Leviticus 20:1', 'Leviticus', 20, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_1.mp3', '', 1761754199, 1761754199),
(50916, 'Leviticus 20:2', 'Leviticus', 20, 2, '«اسراییلیانو ته ووایه: که ستاسو څخه یو څوک یا کوم پردی کس چې په اسراییلو کې اوسیږي د خپلو ماشومانو څخه کوم ماشوم د مولک بت ته د قربانۍ په توګه وړاندې کړي، هغه باید ووژل شي. د قوم خلک دې هغه سنګسار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_2.mp3', '', 1761754199, 1761754199),
(50917, 'Leviticus 20:3', 'Leviticus', 20, 3, 'زه به د هغه کس په خلاف شم او د خپل قوم څخه به یې وشړم، ځکه چې مولک ته د خپلو ماشومانو په قرباني کولو سره یې زما سپېڅلی ځای ناپاک کړی او زما د سپېڅلي نوم سپکاوی یې کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_3.mp3', '', 1761754199, 1761754199),
(50918, 'Leviticus 20:4', 'Leviticus', 20, 4, 'کله چې هغه کس داسې کار وکړي او قوم ورباندې خپلې سترګې پټې کړي او هغه کس ونه وژني،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_4.mp3', '', 1761754199, 1761754199),
(50919, 'Leviticus 20:5', 'Leviticus', 20, 5, 'نو زه به په خپله د هغه کس، د هغه د ټولې کورنۍ او هغو ټولو په خلاف شم چې د هغه سره یوځای زما سره بې وفایي کوي او د مولک عبادت کوي. زه به هغوی د خپل قوم څخه وشړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_5.mp3', '', 1761754199, 1761754199),
(50920, 'Leviticus 20:6', 'Leviticus', 20, 6, 'که چېرې تاسو هغو خلکو ته ورشئ چې کوډې کوي یا کولای شي چې د مړو سره خبرې وکړي، نو زه به ستاسو په خلاف شم او تاسې به د خپل قوم څخه وشړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_6.mp3', '', 1761754199, 1761754199),
(50921, 'Leviticus 20:7', 'Leviticus', 20, 7, 'خپل ځانونه پاک کړئ او سپېڅلي اوسئ، ځکه چې زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_7.mp3', '', 1761754199, 1761754199),
(50922, 'Leviticus 20:8', 'Leviticus', 20, 8, 'زما د فرمانونو څخه پیروي وکړئ. زه څښتن یم چې تاسو پاک او سپېڅلي کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_8.mp3', '', 1761754199, 1761754199),
(50923, 'Leviticus 20:9', 'Leviticus', 20, 9, 'که چېرې یو څوک خپل پلار یا خپلې مور ته ښکنځلې وکړي، نو هغه باید ووژل شي. نو خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_9.mp3', '', 1761754199, 1761754199),
(50924, 'Leviticus 20:10', 'Leviticus', 20, 10, 'که چېرې یو سړی د بل سړي د ښځې سره زنا وکړي، هغه سړی او هغه ښځه دواړه باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_10.mp3', '', 1761754199, 1761754199),
(50925, 'Leviticus 20:11', 'Leviticus', 20, 11, 'که چېرې یو سړی د خپل پلار د ښځو څخه د یوې ښځې سره زنا وکړي، هغه خپل پلار سپکوي، نو هغه سړی او ښځه دواړه باید ووژل شي. خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_11.mp3', '', 1761754199, 1761754199),
(50926, 'Leviticus 20:12', 'Leviticus', 20, 12, 'که چېرې یو سړی د خپلې انږور سره زنا وکړي، هغوی دواړه باید ووژل شي. کوم کار چې هغوی کړی دی، هغه ډېر بد کار دی او خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_12.mp3', '', 1761754199, 1761754199),
(50927, 'Leviticus 20:13', 'Leviticus', 20, 13, 'که چېرې یو سړی د یو بل سړي سره بد کار وکړي، نو هغوی د کرکې وړ کار کړی دی او دواړه باید ووژل شي. خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_13.mp3', '', 1761754199, 1761754199),
(50928, 'Leviticus 20:14', 'Leviticus', 20, 14, 'که چېرې یو سړی د یوې انجلۍ او د هغې د مور دواړو سره واده وکړي، نو درې واړه باید د خپل ډېر بد کار له امله وسوځول شي چې مړه شي، ترڅو ستاسو په منځ کې بدکاري نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_14.mp3', '', 1761754199, 1761754199),
(50929, 'Leviticus 20:15', 'Leviticus', 20, 15, 'که چېرې یو سړی د یو حیوان سره جنسي اړیکې ولري، هغه باید د حیوان سره یوځای ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_15.mp3', '', 1761754199, 1761754199),
(50930, 'Leviticus 20:16', 'Leviticus', 20, 16, 'که چېرې یوه ښځه د یو حیوان سره د جنسي اړیکو د لرلو هڅه وکړي، هغه باید د حیوان سره یوځای ووژل شي. خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_16.mp3', '', 1761754199, 1761754199),
(50931, 'Leviticus 20:17', 'Leviticus', 20, 17, 'که چېرې یو سړی د خپلې سکه یا ناسکه خور سره واده وکړي، دا یوه رسوایي ده. هغوی باید په عام محضر کې د قوم څخه وشړل شي. هغه د خپلې خور سپکاوی کړی دی او مسوولیت به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_17.mp3', '', 1761754199, 1761754199),
(50932, 'Leviticus 20:18', 'Leviticus', 20, 18, 'که چېرې یو سړی د یوې ښځې سره د میاشتینۍ ناروغۍ په دوران کې یوځای شي، هغوی دواړه دې د قوم څخه وشړل شي، ځکه چې هغوی د پاکوالي په اړه مقررات مات کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_18.mp3', '', 1761754199, 1761754199),
(50933, 'Leviticus 20:19', 'Leviticus', 20, 19, 'د خپلې مور د خور یا د خپل پلار د خور سره زنا مه کوئ، ځکه چې دا کار به د یو نژدې خپلوان سپکاوی وي، د دغه بد کار مسوولیت به ستاسو دواړو په غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_19.mp3', '', 1761754199, 1761754199),
(50934, 'Leviticus 20:20', 'Leviticus', 20, 20, 'که چېرې یو سړی د خپل تره د ښځې سره زنا کوي هغه خپل تره سپکوي. مسوولیت به د هغوی په غاړه وي، هغوی به بې اولاده پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_20.mp3', '', 1761754199, 1761754199),
(50935, 'Leviticus 20:21', 'Leviticus', 20, 21, 'که چېرې یو سړی د خپلې ورېندار سره واده وکړي، هغوی به بې اولاده وي. هغه یو ناپاکه کار کړی او د خپل ورور سپکاوی یې کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_21.mp3', '', 1761754199, 1761754199),
(50936, 'Leviticus 20:22', 'Leviticus', 20, 22, 'څښتن وویل: «زما د ټولو فرمانونو او قوانینو څخه پیروي وکړئ، ترڅو تاسو د کنعان د ځمکې څخه چې هلته مو راولم، ونه شړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_22.mp3', '', 1761754199, 1761754199),
(50937, 'Leviticus 20:23', 'Leviticus', 20, 23, 'د هغو خلکو د رواجونو څخه پیروي مه کوئ چې هلته اوسیږي او زه یې د دې په خاطر شړم، ترڅو تاسو وکولای شئ هغې خاورې ته ورننوځئ. زه د هغوی څخه د هغوی د ټولو بدو عملونو له امله کرکه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_23.mp3', '', 1761754199, 1761754199),
(50938, 'Leviticus 20:24', 'Leviticus', 20, 24, 'خو تاسو سره مې د دې غني او حاصلخېزې ځمکې وعده کړې ده، ترڅو هغه ستاسو ملکیت شي او هغه به تاسو ته درکوم. زه ستاسو څښتن خدای یم او تاسو مې د نورو قومونو څخه بېل کړي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_24.mp3', '', 1761754199, 1761754199),
(50939, 'Leviticus 20:25', 'Leviticus', 20, 25, 'له دې امله تاسو باید د پاکو او ناپاکو حیواناتو او مرغانو ترمنځ ښکاره فرق وکړئ. هغه حیوانات یا مرغان چې هغه مې ناپاک اعلان کړي دي، مه خورئ. د هغو په خوړلو به ناپاک شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_25.mp3', '', 1761754199, 1761754199),
(50940, 'Leviticus 20:26', 'Leviticus', 20, 26, 'تاسو به پاک او سپېڅلي شئ، ځکه چې زه څښتن سپېڅلی یم. ما تاسو د نورو قومونو څخه بېل کړي یئ، ترڅو یوازې زما شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_26.mp3', '', 1761754199, 1761754199),
(50941, 'Leviticus 20:27', 'Leviticus', 20, 27, 'هر سړی یا هره ښځه چې دا دعوه کوي چې د مړو سره مشورې کوي، باید ووژل شي. تاسو باید هغه سنګسار کړئ، خون به یې په خپله غاړه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus20_verse_27.mp3', '', 1761754199, 1761754199),
(50942, 'Psalms 140:1', 'Psalms', 140, 1, 'ماته نجات راکړه ای څښتنه له بدکارانو څخه له ظالمانو مې خوندي وساته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_1.mp3', '', 1761754199, 1761754199),
(50943, 'Psalms 140:2', 'Psalms', 140, 2, 'جوړوي بدې دسیسې په خپلو زړونو کې دوی همېشه جنګ او دعوې جوړوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_2.mp3', '', 1761754199, 1761754199),
(50944, 'Psalms 140:3', 'Psalms', 140, 3, 'د مار د نېش په شان دي تېزې د هغوی ژبې د دوی له خولې راوځي خبرې د زهرجن مار په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_3.mp3', '', 1761754199, 1761754199),
(50945, 'Psalms 140:4', 'Psalms', 140, 4, 'ومې ساته ته ای څښتنه د بدکارانو له منګولو له ظالمانو مې خوندي وساته ځکه نقشې جوړوي زما د تباهۍ دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_4.mp3', '', 1761754199, 1761754199),
(50946, 'Psalms 140:5', 'Psalms', 140, 5, 'مغروره خلکو راته ایښی دی دام دوی راته ایښی تیلک او زما په لاره کې یې ایښي دي دامونه چې راګېر مې کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_5.mp3', '', 1761754199, 1761754199),
(50947, 'Psalms 140:6', 'Psalms', 140, 6, 'څښتن ته وایمه زه: «ته زما خدای یې» زارۍ مې واوره ای څښتنه د رحم دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_6.mp3', '', 1761754199, 1761754199),
(50948, 'Psalms 140:7', 'Psalms', 140, 7, 'ای زما څښتن تعالی، ای زما قوي ژغورونکیه د جنګ میدان کې ته زما دپاره سپر شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_7.mp3', '', 1761754199, 1761754199),
(50949, 'Psalms 140:8', 'Psalms', 140, 8, 'پوره نه کړې ارمانونه د بدکارو خلکو ای څښتنه پرېنږدې چې کامیابې دسیسې شي د دوی هسې نه چې مغروره شي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_8.mp3', '', 1761754199, 1761754199),
(50950, 'Psalms 140:9', 'Psalms', 140, 9, 'پرېنږدې چې کامیاب شي دښمنان زما شي راګېر دې دوی په خپلو بدو خبرو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_9.mp3', '', 1761754199, 1761754199),
(50951, 'Psalms 140:10', 'Psalms', 140, 10, 'سرې سکروټې دې راووري هغوی باندې اور ته دې وغورځول شي هغوی او ودې غورځول شي ژورو کندو ته او بیا دې هېڅکله راونه وځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_10.mp3', '', 1761754199, 1761754199),
(50952, 'Psalms 140:11', 'Psalms', 140, 11, 'هغه خلک دې کامیاب نه شي چې په نورو په ناحقه لګوي تورونه بدي دې راشي په ظالمو خلکو او کړي برباد دې هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_11.mp3', '', 1761754199, 1761754199),
(50953, 'Psalms 140:12', 'Psalms', 140, 12, 'څښتنه، زه پوهېږم چې ته کوې د غریبانو دفاع او کوې انصاف د حاجتمندو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_12.mp3', '', 1761754199, 1761754199),
(50954, 'Psalms 140:13', 'Psalms', 140, 13, 'نېکان خلک به په رښتیا وایي ثنا ستا د نوم او صادقان به ستا حضور کې کوي ژوند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms140_verse_13.mp3', '', 1761754199, 1761754199),
(50955, 'Numbers 14:1', 'Numbers', 14, 1, 'کله چې اسراییلیانو د هغو دولسو کسانو راپور چې د کنعان خاوره یې کتلې وه واورېد، نو خلکو ټوله شپه وژړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_1.mp3', '', 1761754199, 1761754199),
(50956, 'Numbers 14:2', 'Numbers', 14, 2, 'او موسی او هارون ته یې داسې ګیله وکړه: «کاشکې مونږ په مصر کې یا دلته په دښته کې مړه شوي وای!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_2.mp3', '', 1761754199, 1761754199),
(50957, 'Numbers 14:3', 'Numbers', 14, 3, 'څښتن ولې مونږ کنعان ته ورولي؟ مونږ به په جنګ کې مړه شو او زمونږ ښځې او ماشومان به اسیران شي. ایا دا به ښه نه وي چې بېرته مصر ته لاړ شو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_3.mp3', '', 1761754199, 1761754199),
(50958, 'Numbers 14:4', 'Numbers', 14, 4, 'بیا هغوی یو بل ته وویل: «راځئ چې خپل مشر غوره کړو او بېرته مصر ته لاړ شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_4.mp3', '', 1761754199, 1761754199),
(50959, 'Numbers 14:5', 'Numbers', 14, 5, 'موسی او هارون د ټول قوم په مخکې څښتن ته سجده وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_5.mp3', '', 1761754199, 1761754199),
(50960, 'Numbers 14:6', 'Numbers', 14, 6, 'د نون زوی یوشع او د یفنه زوی کالیب چې د هغو کسانو څخه وو چې هغه خاوره یې کتلې وه، له خفګانه خپل کالي وشکول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_6.mp3', '', 1761754199, 1761754199),
(50961, 'Numbers 14:7', 'Numbers', 14, 7, 'او خلکو ته یې وویل: «هغه ځمکه چې مونږ وکتله هغه ډېره ښه ځمکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_7.mp3', '', 1761754199, 1761754199),
(50962, 'Numbers 14:8', 'Numbers', 14, 8, 'که چېرې خدای زمونږ څخه راضي وي، هغه به مو هلته یوسي او هغه غني او حاصلخېزه ځمکه به راته راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_8.mp3', '', 1761754199, 1761754199),
(50963, 'Numbers 14:9', 'Numbers', 14, 9, 'نو د څښتن په وړاندې سرکښي مه کوئ او د هغه ځای د خلکو څخه مه وېرېږئ. مونږ به په اسانۍ سره په هغوی باندې بریالي شو. څښتن زمونږ سره مل دی او هغو خدایانو ته یې ماتې ورکړې ده چې د هغوی ساتنه یې کوله. نو مه وېرېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_9.mp3', '', 1761754199, 1761754199),
(50964, 'Numbers 14:10', 'Numbers', 14, 10, 'ټول قوم ګواښ وکړ چې موسی او هارون سنګسار کړي چې مړه شي. خو ناڅاپه د څښتن جلال په سپېڅلې خېمې باندې ټولو اسراییلیانو ته راښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_10.mp3', '', 1761754199, 1761754199),
(50965, 'Numbers 14:11', 'Numbers', 14, 11, 'څښتن موسی ته وویل: «ترڅو پورې به دا خلک ما نه مني؟ که څه هم ما هغوی ته ډېرې معجزې ښودلې دي، خو بیاهم هغوی په ما باندې باور نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_11.mp3', '', 1761754199, 1761754199),
(50966, 'Numbers 14:12', 'Numbers', 14, 12, 'زه به په هغوی باندې وبا نازله کړم او له منځه به یې یوسم، خو ستا څخه به د یو داسې قوم نیکه جوړ کړم چې د هغوی د قوم څخه لوی او قوي وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_12.mp3', '', 1761754199, 1761754199),
(50967, 'Numbers 14:13', 'Numbers', 14, 13, 'خو موسی څښتن ته وویل: «تا په خپل قدرت سره دا قوم د مصر څخه راوویست. کله چې مصریان واوري چې تا د خپل قوم سره داسې وکړل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_13.mp3', '', 1761754199, 1761754199),
(50968, 'Numbers 14:14', 'Numbers', 14, 14, 'نو هغوی به دا د کنعان خلکو ته ووایي. دغه خلک له مخکې نه خبر دي چې ته، ای څښتنه زمونږ سره مل یې او کله چې ستا ورېځ زمونږ دپاسه ودریږي، نو مونږ ته مخامخ ښکارې. د ورځې له خوا د ستنې په شان ورېځ کې زمونږ په مخکې ځې او د شپې له خوا د ستنې په شان اور کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_14.mp3', '', 1761754199, 1761754199),
(50969, 'Numbers 14:15', 'Numbers', 14, 15, 'اوس که چېرې ته خپل ټول قوم ووژنې، نو هغه قومونه چې ستا د شهرت په هکله یې اورېدلي دي داسې به وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_15.mp3', '', 1761754199, 1761754199),
(50970, 'Numbers 14:16', 'Numbers', 14, 16, 'چې خپل خلک دې ځکه په دښته کې ووژل چې تا نه شو کولای هغوی هغې ځمکې ته ورولې چې د هغې وعده دې ورسره کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_16.mp3', '', 1761754199, 1761754199),
(50971, 'Numbers 14:17', 'Numbers', 14, 17, 'ای څښتنه، مونږ ته دې خپل لوی قدرت وښایه او هغه وعده دې پوره کړه چې کړې دې وه. تا ویلي وو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_17.mp3', '', 1761754199, 1761754199),
(50972, 'Numbers 14:18', 'Numbers', 14, 18, '‹زه څښتن زر نه په قهرېږم او ډېره مینه او وفاداري کوم او ګناه او سرغړونه بخښم. خو بیاهم اولادونو او لمسیو ته تر درېم او څلورم نسله پورې د هغوی د پلرونو د ګناهونو په خاطر سزا ورکوم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_18.mp3', '', 1761754199, 1761754199),
(50973, 'Numbers 14:19', 'Numbers', 14, 19, 'ته رحیم یې او ته د خلکو سره ډېر ښه چلند کوې، که څه هم د ښې رویې وړ نه دي. نو مهرباني وکړه دا قوم داسې وبخښه لکه څنګه چې دې له هغه وخته راهیسې بخښلی دی چې هغوی د مصر څخه راووتل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_19.mp3', '', 1761754199, 1761754199),
(50974, 'Numbers 14:20', 'Numbers', 14, 20, 'څښتن په ځواب کې وویل: «لکه څنګه چې تا سوال وکړ زه هغوی بخښم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_20.mp3', '', 1761754199, 1761754199),
(50975, 'Numbers 14:21', 'Numbers', 14, 21, 'خو زه په خپل ذات او خپل جلال باندې چې ټوله ځمکه ډکوي قسم خورم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_21.mp3', '', 1761754199, 1761754199),
(50976, 'Numbers 14:22', 'Numbers', 14, 22, 'د دې خلکو څخه به هېڅوک ژوندی پاتې نه شي چې هغې خاورې ته ورننوځي. هغوی زما جلال او معجزې چې په مصر او دښته کې مې ښودلې وې لیدلې دي، خو هغوی زه څو څو ځلې ازمایلی یم او زما د امر څخه یې سرغړونه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_22.mp3', '', 1761754199, 1761754199),
(50977, 'Numbers 14:23', 'Numbers', 14, 23, 'هغوی به هېڅکله هغې خاورې ته ورداخل نه شي چې د هغوی د نیکونو سره مې وعده کړې ده. هغه چا چې زه یې نه یم منلی، هغه به هېڅکله هم ورداخل نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_23.mp3', '', 1761754199, 1761754199),
(50978, 'Numbers 14:24', 'Numbers', 14, 24, 'خو په دې خاطر چې زما خدمتګار کالیب د نورو په شان نه دی او هغه ماته وفادار پاتې شوی دی، زه به هغه هغې ځمکې ته ورولم چې هغه کتلې وه او هغه ځمکه به د هغه د اولادې ملکیت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_24.mp3', '', 1761754199, 1761754199),
(50979, 'Numbers 14:25', 'Numbers', 14, 25, 'څرنګه چې عمالیقیان او کنعانیان په درو کې اوسیږي، نو سهار بېرته راوګرځئ او د سرې بحیرې له لارې د دښتې خواته لاړ شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_25.mp3', '', 1761754199, 1761754199),
(50980, 'Numbers 14:26', 'Numbers', 14, 26, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_26.mp3', '', 1761754199, 1761754199),
(50981, 'Numbers 14:27', 'Numbers', 14, 27, '«ترڅو پورې به دا بدکاره قوم زما په ضد شکایت کوي؟ ما دا شکایتونه ډېر واورېدل!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_27.mp3', '', 1761754199, 1761754199),
(50982, 'Numbers 14:28', 'Numbers', 14, 28, 'اوس هغوی ته دغه ځواب ورکړئ: ‹زه په خپل ذات باندې قسم خورم، څه چې تاسو غوښتي دي هماغسې به درباندې وکړم. ما څښتن دا خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_28.mp3', '', 1761754199, 1761754199),
(50983, 'Numbers 14:29', 'Numbers', 14, 29, 'تاسو به مړه شئ او ستاسو مړي به په دې دښته کې خپاره شي. ستاسو څخه به هېڅوک چې عمر یې د شلو کالو څخه زیات وي هغې خاورې ته داخل نه شي، ځکه چې تاسو زما په خلاف شکایت کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_29.mp3', '', 1761754199, 1761754199),
(50984, 'Numbers 14:30', 'Numbers', 14, 30, 'ما قسم خوړلی ؤ چې تاسو به هلته واوسېږئ، خو پرته له کالیب او یوشع څخه به نور هېڅوک هلته ژوند ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_30.mp3', '', 1761754199, 1761754199),
(50985, 'Numbers 14:31', 'Numbers', 14, 31, 'تاسو ویل چې اولادونه به مو اسیران شي، خو زه به هغوی هغې ځمکې ته راولم چې تاسو رد کړې وه او هغه به یې وطن وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_31.mp3', '', 1761754199, 1761754199),
(50986, 'Numbers 14:32', 'Numbers', 14, 32, 'خو تاسو به په دې دښته کې مړه شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_32.mp3', '', 1761754199, 1761754199),
(50987, 'Numbers 14:33', 'Numbers', 14, 33, 'ستاسو اولادونه به په دښته کې څلوېښت کاله سرګردانه ګرځي او ستاسو د بې وفایۍ له امله به ځوریږي، ترڅو پورې چې تاسو ټول مړه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_33.mp3', '', 1761754199, 1761754199),
(50988, 'Numbers 14:34', 'Numbers', 14, 34, 'تاسو به څلوېښت کاله یعنې هغه څلوېښت ورځې چې تاسو هغه ځمکه کتلې وه د هرې ورځې په ځای به یو کال د خپلې ګناه په خاطر ځورېږئ. تاسو به زما د مخالفت په معنی باندې پوه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_34.mp3', '', 1761754199, 1761754199),
(50989, 'Numbers 14:35', 'Numbers', 14, 35, 'زه قسم خورم چې تاسو بدکاره خلکو سره به چې زما په وړاندې راټول شوي یئ دا کار وکړم. تاسو هر یو به په دښته کې مړه شئ. دا زما یعنې څښتن خبره ده.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_35.mp3', '', 1761754199, 1761754199),
(50990, 'Numbers 14:36', 'Numbers', 14, 36, 'هغو کسانو چې د ځمکې د کتلو دپاره لېږل شوي وو، غلط خبر راوړی ؤ او قوم یې دې ته مجبور کړی ؤ چې د څښتن په ضد شکایت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_36.mp3', '', 1761754199, 1761754199),
(50991, 'Numbers 14:37', 'Numbers', 14, 37, 'نو هغه ورباندې یوه وژونکې ناروغي نازله کړه او هغوی یې ووژل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_37.mp3', '', 1761754199, 1761754199),
(50992, 'Numbers 14:38', 'Numbers', 14, 38, 'خو یوشع او کالیب یې ژوندي پرېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_38.mp3', '', 1761754199, 1761754199),
(50993, 'Numbers 14:39', 'Numbers', 14, 39, 'کله چې موسی د اسراییلو قوم ته د څښتن پیغام ورساوه، هغوی ډېر غمجن شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_39.mp3', '', 1761754199, 1761754199),
(50994, 'Numbers 14:40', 'Numbers', 14, 40, 'نو هغوی سهار وختي پاڅېدل او ځانونه یې تیار کړل چې د کنعان د غرنۍ سیمې په لور روان شي. هغوی وویل: «دا زمونږ ګناه وه چې د څښتن په هکله مو شکایت وکړ. راځئ چې هغې ځمکې ته لاړ شو چې هغه یې راسره وعده کړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_40.mp3', '', 1761754199, 1761754199),
(50995, 'Numbers 14:41', 'Numbers', 14, 41, 'خو موسی په ځواب کې وویل: «بیا ولې د څښتن د امر څخه سرغړونه کوئ؟ تاسو به بریالي نه شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_41.mp3', '', 1761754199, 1761754199),
(50996, 'Numbers 14:42', 'Numbers', 14, 42, 'مه ځئ. څښتن تاسو سره مل نه دی او ستاسو دښمنان به تاسو ته ماتې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_42.mp3', '', 1761754199, 1761754199),
(50997, 'Numbers 14:43', 'Numbers', 14, 43, 'کله چې تاسو د عمالیقیانو او کنعانیانو سره مخامخ شئ، تاسو به په جګړه کې مړه شئ. څښتن به تاسو سره مل نه وي، ځکه چې تاسو د هغه د پیروۍ څخه انکار کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_43.mp3', '', 1761754199, 1761754199),
(50998, 'Numbers 14:44', 'Numbers', 14, 44, 'خو بیاهم هغوی جرات وکړ چې غرنۍ سیمې ته لاړ شي، که څه هم نه موسی او نه د څښتن د لوظ صندوق ورسره لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_44.mp3', '', 1761754199, 1761754199),
(50999, 'Numbers 14:45', 'Numbers', 14, 45, 'عمالیقیان او کنعانیان د غرنۍ سیمې څخه راښکته شول، اسراییلیانو ته یې ماتې ورکړه او د حرمه تر ښاره پورې ورپسې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers14_verse_45.mp3', '', 1761754199, 1761754199),
(51000, 'Exodus 36:1', 'Exodus', 36, 1, 'بزل ییل، اهولیاب او نور کارګران چې څښتن ورته مهارت او پوهه ورکړې ده د څښتن د حکم سره سم به سپېڅلې خېمه جوړه او تیاره کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_1.mp3', '', 1761754199, 1761754199),
(51001, 'Exodus 36:2', 'Exodus', 36, 2, 'بیا موسی بزل ییل او اهولیاب او ټول ماهر خلک چې څښتن ورته توان ورکړی ؤ او غوښتل یې چې کار وکړي، راوغوښتل چې راشي او کار پیل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_2.mp3', '', 1761754199, 1761754199),
(51002, 'Exodus 36:3', 'Exodus', 36, 3, 'هغوی د موسی څخه هغه ټولې نذرانې چې د اسراییلو خلکو د سپېڅلې خېمې د جوړولو د کار دپاره راوړې وې، واخیستلې. خو خلکو به موسی ته هر سهار د خپلې خوښې نذرانې راوړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_3.mp3', '', 1761754199, 1761754199),
(51003, 'Exodus 36:4', 'Exodus', 36, 4, 'نو هغو ټولو ماهرو کسبګرو چې په سپېڅلې خېمې باندې یې کار کاوه، خپل کار پرېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_4.mp3', '', 1761754199, 1761754199),
(51004, 'Exodus 36:5', 'Exodus', 36, 5, 'او موسی ته یې وویل: «د هغه کار دپاره چې څښتن یې حکم کړی دی، خلک له اړتیا نه زیاتې نذرانې راوړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_5.mp3', '', 1761754199, 1761754199),
(51005, 'Exodus 36:6', 'Exodus', 36, 6, 'بیا موسی حکم وکړ او هغوی دا خبره ټول کمپ ته ورسوله: «هېڅ سړی یا ښځه دې د سپېڅلې خېمې دپاره نور هېڅ شی د نذرانې په توګه نه راوړي.» نو خلک نور د نذرانو د راوړلو څخه منع کړای شول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_6.mp3', '', 1761754199, 1761754199),
(51006, 'Exodus 36:7', 'Exodus', 36, 7, 'ځکه څه چې مخکې راوړل شوي وو، هغه د ټول کار د سرته رسولو دپاره بس وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_7.mp3', '', 1761754199, 1761754199),
(51007, 'Exodus 36:8', 'Exodus', 36, 8, 'د کارګرانو څخه ټولو ماهرو کسانو د ښه کتان او د ابي، بانجاني او سرو وړیو د لسو پردو څخه سپېڅلې خېمه جوړه کړه او په هغو کې یې د اسماني مخلوقاتو نقشونه ګلدوزي کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_8.mp3', '', 1761754199, 1761754199),
(51008, 'Exodus 36:9', 'Exodus', 36, 9, 'د ټولو پردو اندازه یوشان وه، دولس متره اوږدې او دوه متره پلنې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_9.mp3', '', 1761754199, 1761754199),
(51009, 'Exodus 36:10', 'Exodus', 36, 10, 'د دې پردو څخه پنځه پردې سره یوځای شوې او یوه جوړه ورڅخه جوړه شوه او دوهمه جوړه د نورو پنځو پردو څخه جوړه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_10.mp3', '', 1761754199, 1761754199),
(51010, 'Exodus 36:11', 'Exodus', 36, 11, 'هغوی په هره جوړه کې د باندینۍ پردې په څنډه باندې د ابي رنګه ټوټې کړۍ ګانې جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus36_verse_11.mp3', '', 1761754199, 1761754199);